// src/lib/productCopy/index.js
// Curated, source-checked product copy (supplements the backoffice texts).
// Data: src/content/productCopy/de.json (generated by ./build.mjs).
// Relative imports only, so node --test can import this file as well.
// App code imports ./server.js ("@/lib/productCopy/server"), never this file:
// the JSON holds every draft and must stay out of client bundles.
import de from "../../content/productCopy/de.json" with { type: "json" };
import { buildFaqJsonLd, createProductCopyStore, isPublishedCopy, metadataOverride, previewCopy } from "./core.js";

const stores = { de: createProductCopyStore(de, { locale: "de" }) };

/**
 * Published view for a product page, or null.
 * Only locale 'de' and only fields with a valid text-hash approval
 * (./approvals.js); FAQ only the approved question/answer pairs.
 * @param {string} categorySlug  first URL segment after /produkte
 * @param {string} productSlug   path_field of the product
 * @param {string} locale
 */
export function getProductCopy(categorySlug, productSlug, locale) {
  const store = stores[locale];
  return store ? store.get(categorySlug, productSlug, locale) : null;
}

/**
 * Like getProductCopy, plus { matchedBy, canonicalPath, staleCatalogPath }.
 * Call it after the page's category-redirect check, with the live params;
 * use canonicalPath (not copy.catalog.path) for canonical/hreflang.
 */
export function resolveProductCopy(categorySlug, productSlug, locale) {
  const store = stores[locale];
  return store ? store.resolve(categorySlug, productSlug, locale) : null;
}

/**
 * Draft copy (preview, tests), approved or not. German only.
 * Without arguments: every entry.
 */
export function getProductCopyDraft(categorySlug, productSlug) {
  return stores.de.draft(categorySlug, productSlug);
}

/** Dev preview of the draft (see core.previewCopy); never for production pages. */
export function getProductCopyPreview(categorySlug, productSlug) {
  return previewCopy(stores.de.draft(categorySlug, productSlug));
}

export function listProductCopyKeys() {
  return stores.de.keys();
}

export { buildFaqJsonLd, isPublishedCopy, metadataOverride };
